{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Integrative sessions focused on whole-person wellbeing. Practical planning tools and tailored session frameworks." />
  <link rel="icon" href="data:;base64,iVBORw0KGgo=" />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-root">
  <header class="site-header">
    <div class="brand">
      <div class="logo-mark" aria-hidden="true"></div>
      <div class="brand-copy">
        <strong class="name">{{BUSINESS_NAME}}</strong>
        <span class="tag">{{TAGLINE}}</span>
      </div>
    </div>
    <nav class="site-nav" aria-label="Primary">
      <a href="/">Explore</a>
      <a href="/services.html">Services</a>
      <a href="/conditions.html">Conditions</a>
      <a href="/approach.html">Method</a>
      <a href="/pricing.html">Pricing</a>
      <a href="/about.html">About</a>
      <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
      <a href="/contact.html" class="muted">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero reveal" id="hero">
      <svg class="bg-pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern"/></svg>
      <div class="container">
        <h1>Practical integrative care tailored to your life rhythm.</h1>
        <p>Guided sessions and short home practices that connect symptoms, routines, and meaningful small shifts — designed for people with busy days and complex needs.</p>
        <div class="hero-ctas">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/about.html">Meet the team</a>
        </div>
      </div>
    </section>

    <section class="story reveal" id="story">
      <div class="container narrow">
        <h2>Where care meets your schedule</h2>
        <p>We combine evidence-informed modalities into clear, small-step plans. You'll leave with a focused roadmap for the weeks that follow — not an overwhelming list of tasks.</p>
        <ul class="values">
          <li><strong>Integrative framing</strong><span>Clinical insight with lifestyle practices.</span></li>
          <li><strong>Actionable steps</strong><span>Short, sustainable practices you can actually keep.</span></li>
          <li><strong>Collaborative planning</strong><span>We design with you, not for you.</span></li>
        </ul>
      </div>
    </section>

    <section class="framework reveal" id="framework">
      <div class="container">
        <h2>Our session framework</h2>
        <ol class="framework-list">
          <li><strong>Map</strong><span>Clarify symptoms, routines, and context.</span></li>
          <li><strong>Craft</strong><span>Choose modalities and simple practices aligned to goals.</span></li>
          <li><strong>Plan</strong><span>Build a week-by-week, realistic roadmap.</span></li>
          <li><strong>Support</strong><span>Tools for home practice and optional check-ins.</span></li>
        </ol>
      </div>
    </section>

    <section class="offers reveal" id="offers">
      <div class="container">
        <h2>Programs & signature sessions</h2>
        <div class="masonry">
          <article class="card">
            <h3>Foundations Consultation</h3>
            <p>60-minute intake to map your history, priorities, and key leverage points.</p>
            <div class="price">$195</div>
            <a class="btn" href="/book.html">Book a Foundation</a>
          </article>

          <article class="card">
            <h3>Focused Strategy</h3>
            <p>90-minute deep session for planning a 6-week self-guided program with measurable steps.</p>
            <div class="price">$325</div>
            <a class="btn" href="/book.html">Reserve Strategy</a>
          </article>

          <article class="card">
            <h3>VIP Day</h3>
            <p>An intensive half- or full-day to overhaul a health goal, create materials, and leave with an executable plan.
            Ideal for pressing transitions.</p>
            <div class="price">From $1,250</div>
            <a class="btn" href="/book.html">Inquire about VIP Day</a>
          </article>
        </div>

        <div class="widget-area">
          <h4>Session Planner (compact)</h4>
          <div class="session-planner compact" id="planner-compact">
            <label>Primary goal<input type="text" name="goal" placeholder="Better sleep, reduce flare, steady energy"></label>
            <label>Weekly time<select name="time"><option>30 min</option><option selected>60 min</option><option>90+ min</option></select></label>
            <button class="btn build" data-target="planner-compact">Build plan</button>
            <div class="result">
              <textarea readonly></textarea>
              <div class="actions"><button class="copy">Copy</button><button class="download">Download</button></div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="pricing reveal" id="pricing">
      <div class="container">
        <h2>Pricing snapshot</h2>
        <p>Transparent, tiered options so you choose the intensity that suits your life and budget.</p>
        <div class="plans">
          <div class="plan">
            <h3>Starter Sequence</h3>
            <p>Three short sessions across four weeks to establish simple routines.</p>
            <div class="price">$495</div>
            <a class="btn" href="/pricing.html">See details</a>
          </div>
          <div class="plan featured">
            <h3>Core Roadmap</h3>
            <p>Six-week guided plan with templates and one mid-cycle check-in.</p>
            <div class="price">$975</div>
            <a class="btn" href="/pricing.html">Choose Core</a>
          </div>
          <div class="plan">
            <h3>Ongoing Support</h3>
            <p>Monthly coaching and priority scheduling for complex cases.</p>
            <div class="price">Starting at $180/mo</div>
            <a class="btn" href="/pricing.html">Request Info</a>
          </div>
        </div>

        <div class="widget-area">
          <h4>Session Planner (full)</h4>
          <div class="session-planner" id="planner-full">
            <label>Primary goal<input type="text" name="goal" placeholder="What is the main outcome you want?"></label>
            <label>Concerns<textarea name="concerns" placeholder="List meds, triggers, or recurring issues"></textarea></label>
            <fieldset>
              <legend>Preferred approaches</legend>
              <label><input type="checkbox" name="modality" value="movement"> Movement & breath</label>
              <label><input type="checkbox" name="modality" value="nutrition"> Nutrition support</label>
              <label><input type="checkbox" name="modality" value="mind"> Mind-body tools</label>
              <label><input type="checkbox" name="modality" value="herbal"> Botanical guidance</label>
            </fieldset>
            <label>Time availability<select name="time"><option>15-30 min/wk</option><option selected>30-60 min/wk</option><option>60+ min/wk</option></select></label>
            <label>Intensity<select name="intensity"><option>Low</option><option selected>Moderate</option><option>High</option></select></label>
            <button class="btn build" data-target="planner-full">Create personalized plan</button>
            <div class="result">
              <textarea readonly></textarea>
              <div class="actions"><button class="copy">Copy</button><button class="download">Download</button></div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="testimonials reveal" id="testimonials">
      <div class="container narrow">
        <h2>Client reflections</h2>
        <blockquote>
          "A clear plan that matched my week — small steps that actually stuck. I felt supported rather than overwhelmed."
          <cite>— J., {{CITY}}</cite>
        </blockquote>
        <blockquote>
          "The VIP Day helped me create a realistic protocol and materials I could use with my family. Worth every moment."
          <cite>— M., {{STATE}}</cite>
        </blockquote>
      </div>
    </section>

    <section class="cta reveal" id="final-cta">
      <div class="container">
        <h2>Ready to plan a session that fits your life?</h2>
        <p>Schedule a focused conversation and leave with a usable roadmap.</p>
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="muted">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="container">
      <small>&copy; <span id="year"></span> {{BUSINESS_NAME}}. Not medical advice. Consult licensed providers for diagnosis and treatment.</small>
      <nav class="footer-nav"><a href="/privacy.html">Privacy</a> <a href="/terms.html">Terms</a></nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
